import * as U from '../ui.js';
let filter='all',q='';
const update=U.mount(()=>{let items=U.db.university_info.filter(x=>(filter==='all'||x.info_type===filter)&&(x.title+' '+x.content+' '+x.location).toLowerCase().includes(q.toLowerCase()));return U.heading('Find your way around','Campus, a little less confusing.','Your saved contacts, useful places, rules, and university guides.',U.button('Save information','university_info'))+`<div class="toolbar"><div class="tabs">${['all','office','rule','contact','link','note','club'].map(t=>`<button data-info-filter="${t}" class="${filter===t?'active':''}">${t==='all'?'All information':t.charAt(0).toUpperCase()+t.slice(1)+'s'}</button>`).join('')}</div><input class="search" id="info-search" aria-label="Search information" placeholder="Find a contact, office, or guide…" value="${U.esc(q)}"></div><div class="grid3">${items.map(x=>`<article class="card info-card">${U.tag(x.info_type,'blue')}<h2>${U.esc(x.title)}</h2><p>${U.esc(x.content)}</p>${x.location?`<div class="small muted" style="line-height:1.8">${U.icon('pin')} ${U.esc(x.location)}</div>`:''}${x.contact_name?`<p><strong>${U.esc(x.contact_name)}</strong>${x.contact_email?`<br><a class="text-link" href="mailto:${U.esc(x.contact_email)}">${U.esc(x.contact_email)}</a>`:''}${x.contact_phone?`<br><a href="tel:${U.esc(x.contact_phone)}">${U.esc(x.contact_phone)}</a>`:''}</p>`:''}<footer>${x.url&&/^https?:\/\//.test(x.url)?`<a class="text-link" target="_blank" rel="noopener" href="${U.esc(x.url)}">Open saved link ↗</a>`:'<span class="small muted">Saved to your hub</span>'}<span style="margin-left:auto">${U.edit('university_info',x.id)}</span></footer></article>`).join('')||U.empty('No matching information. Save something useful or try another search.')}</div><div class="note" style="margin-top:22px">${U.icon('info')}<span>This hub contains illustrative information and placeholder contacts. Confirm procedures and requirements with your university.</span></div>`});
document.addEventListener('click',e=>{let b=e.target.closest('[data-info-filter]');if(b){filter=b.dataset.infoFilter;update()}});document.addEventListener('input',e=>{if(e.target.id==='info-search'){let p=e.target.selectionStart;q=e.target.value;update();let el=document.querySelector('#info-search');el.focus();el.setSelectionRange(p,p)}});
